function setLanguage(language) {
  const locale = languageCopy[language] ? language : 'zh';
  activeLanguage = locale;
  const translations = languageCopy[locale] || {};
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  let node;

  while ((node = walker.nextNode())) {
    if (node.parentElement?.closest('script, style, select option')) continue;
    if (node.__sourceText === undefined) node.__sourceText = node.nodeValue;
    const source = node.__sourceText;
    const trimmed = source.trim();
    if (!trimmed) continue;
    const leading = source.match(/^\s*/)?.[0] || '';
    const trailing = source.match(/\s*$/)?.[0] || '';
    node.nodeValue = `${leading}${translations[trimmed] || trimmed}${trailing}`;
  }

  document.querySelectorAll('[aria-label], [alt], [title]').forEach((element) => {
    ['ariaLabel', 'alt', 'title'].forEach((attribute) => {
      const attributeName = attribute === 'ariaLabel' ? 'aria-label' : attribute;
      if (!element.hasAttribute(attributeName)) return;
      const sourceKey = `source${attribute[0].toUpperCase()}${attribute.slice(1)}`;
      if (element.dataset[sourceKey] === undefined) element.dataset[sourceKey] = element.getAttribute(attributeName);
      const source = element.dataset[sourceKey];
      element.setAttribute(attributeName, languageAttributeCopy[locale]?.[source] || translations[source] || source);
    });
  });

  document.documentElement.lang = { zh: 'zh-CN', ko: 'ko', ja: 'ja', en: 'en' }[locale];
  document.title = pageTitles[locale]?.[document.body.dataset.page || 'home'] || pageTitles.zh.home;
  if (languageSelect) languageSelect.value = locale;
  try { localStorage.setItem('bucheon-language', locale); } catch { /* Storage may be disabled in private browsing. */ }
}

let savedLanguage = 'zh';
try { savedLanguage = localStorage.getItem('bucheon-language') || 'zh'; } catch { /* Keep the default language. */ }
setLanguage(savedLanguage);
languageSelect?.addEventListener('change', (event) => setLanguage(event.target.value));

document.querySelectorAll('.filter-button').forEach((button) => {
  button.addEventListener('click', () => {
    const filter = button.dataset.filter;
    document.querySelectorAll('.filter-button').forEach((item) => {
      const isActive = item === button;
      item.classList.toggle('is-active', isActive);
      item.setAttribute('aria-pressed', String(isActive));
    });
    document.querySelectorAll('.exhibition-card').forEach((card) => {
      card.classList.toggle('is-hidden', filter !== 'all' && card.dataset.category !== filter);
    });
  });
});

const vrLaunch = document.querySelector('#vr-launch');
const vrModal = document.querySelector('#vr-modal');
const vrClose = document.querySelector('#vr-close');
const vrContainer = document.querySelector('#vr-scene-container');
const vrLoading = document.querySelector('#vr-loading');
let aframeLoad;

function loadAFrame() {
  if (window.AFRAME) return Promise.resolve();
  if (aframeLoad) return aframeLoad;
  aframeLoad = new Promise((resolve, reject) => {
    const script = document.createElement('script');
    script.src = 'https://aframe.io/releases/1.6.0/aframe.min.js';
    script.onload = resolve;
    script.onerror = reject;
    document.head.appendChild(script);
  });
  return aframeLoad;
}

function closeVr() {
  if (!vrModal) return;
  const scene = vrContainer?.querySelector('a-scene');
  if (scene?.is('vr-mode')) scene.exitVR();
  vrModal.hidden = true;
  document.body.style.overflow = '';
  vrLaunch?.focus();
}

vrLaunch?.addEventListener('click', async () => {
  if (!vrModal || !vrContainer || !vrLoading) return;
  vrModal.hidden = false;
  document.body.style.overflow = 'hidden';
  vrClose?.focus();
  if (vrContainer.querySelector('a-scene')) return;

  try {
    await loadAFrame();
    const scene = document.createElement('a-scene');
    scene.setAttribute('embedded', '');
    scene.setAttribute('vr-mode-ui', 'enabled: true');
    scene.setAttribute('device-orientation-permission-ui', 'enabled: true');
    scene.setAttribute('loading-screen', 'enabled: false');
    scene.setAttribute('background', 'color: #26382d');

    const sky = document.createElement('a-sky');
    sky.setAttribute('src', 'https://cdn.aframe.io/360-image-gallery-boilerplate/img/sechelt.jpg');
    sky.setAttribute('rotation', '0 -90 0');
    const camera = document.createElement('a-entity');
    camera.setAttribute('camera', 'active: true');
    camera.setAttribute('look-controls', 'touchEnabled: true; mouseEnabled: true');
    camera.setAttribute('position', '0 1.6 0');
    scene.append(sky, camera);
    scene.addEventListener('loaded', () => { vrLoading.hidden = true; }, { once: true });
    sky.addEventListener('materialtextureloaded', () => { vrLoading.hidden = true; }, { once: true });
    vrContainer.appendChild(scene);
    window.setTimeout(() => { vrLoading.hidden = true; }, 12000);
  } catch {
    vrLoading.textContent = '全景组件加载失败，请检查网络连接后重试。';
  }
});

vrClose?.addEventListener('click', closeVr);
vrModal?.addEventListener('click', (event) => { if (event.target === vrModal) closeVr(); });
document.addEventListener('keydown', (event) => { if (event.key === 'Escape' && vrModal && !vrModal.hidden) closeVr(); });

const arModal = document.querySelector('#ar-modal');
const arTitle = document.querySelector('#ar-title');
const arItemImage = document.querySelector('#ar-item-image');
const arDescription = document.querySelector('#ar-description');
const arClose = document.querySelector('#ar-close');
const arOfficialLink = document.querySelector('#ar-official-link');
let lastArTrigger;

function closeAr() {
  if (!arModal) return;
  arModal.hidden = true;
  document.body.style.overflow = '';
  lastArTrigger?.focus();
}

document.querySelectorAll('.ar-open').forEach((button) => {
  button.addEventListener('click', () => {
    if (!arModal || !arItemImage || !arTitle || !arDescription || !arOfficialLink) return;
    lastArTrigger = button;
    const title = button.dataset.title || '展品图片导览';
    const cardDescription = button.closest('.collection-card')?.querySelector('.collection-card-body > p:not(.collection-original)')?.textContent.trim();
    const description = cardDescription || button.dataset.description || '';
    arModal.hidden = false;
    document.body.style.overflow = 'hidden';
    arTitle.textContent = languageCopy[activeLanguage]?.[title] || title;
    arDescription.textContent = languageCopy[activeLanguage]?.[description] || description;
    arItemImage.src = button.dataset.image || '';
    arItemImage.alt = arTitle.textContent;
    arOfficialLink.href = button.dataset.official || 'https://www.bcmuseum.or.kr/ko/collection/';
  });
});

arClose?.addEventListener('click', closeAr);
arModal?.addEventListener('click', (event) => { if (event.target === arModal) closeAr(); });
document.addEventListener('keydown', (event) => { if (event.key === 'Escape' && arModal && !arModal.hidden) closeAr(); });

