let activeMapPlace = 'city';
function selectMuseumMap(placeId) {
  const place = museumMapPlaces[placeId] || museumMapPlaces.city;
  activeMapPlace = placeId in museumMapPlaces ? placeId : 'city';
  const label = place.labels[activeLanguage] || place.labels.zh;
  const query = encodeURIComponent(place.query);
  const mapFrame = document.querySelector('#google-map');
  const mapName = document.querySelector('#map-place-name');
  const mapAddress = document.querySelector('#map-address');
  const mapOpenLink = document.querySelector('#map-open-link');

  document.querySelectorAll('.map-place').forEach((button) => {
    const isActive = button.dataset.mapPlace === activeMapPlace;
    button.classList.toggle('is-active', isActive);
    button.setAttribute('aria-pressed', String(isActive));
  });

  if (mapName) mapName.textContent = label;
  if (mapAddress) mapAddress.textContent = place.addresses[activeLanguage] || place.addresses.zh;
  if (mapFrame) {
    mapFrame.src = `https://maps.google.com/maps?q=${query}&output=embed`;
    mapFrame.title = `${label} Google Maps`;
  }
  if (mapOpenLink) mapOpenLink.href = `https://www.google.com/maps/search/?api=1&query=${query}`;
}

document.querySelectorAll('.map-place').forEach((button) => {
  button.addEventListener('click', () => selectMuseumMap(button.dataset.mapPlace));
});
if (document.querySelector('#google-map')) {
  selectMuseumMap(activeMapPlace);
  languageSelect?.addEventListener('change', () => selectMuseumMap(activeMapPlace));
}
